from pysat.solvers import Glucose4
from itertools import combinations

# Variables:
# x[v][val] for v in 0..17, val in 0..33
# e[edge_idx][diff] for edge_idx in 0..32, diff in 1..33

def var_x(v, val):
    return v * 34 + val + 1

def var_e(edge_idx, diff):
    return 18 * 34 + edge_idx * 33 + diff

edges = []
for g in range(6):
    edges.append((g*3 + 0, g*3 + 1))
    edges.append((g*3 + 1, g*3 + 2))
    edges.append((g*3 + 0, g*3 + 2))

for g in range(5):
    edges.append((g*3 + 0, (g+1)*3 + 0))
    edges.append((g*3 + 1, (g+1)*3 + 1))
    edges.append((g*3 + 2, (g+1)*3 + 2))

solver = Glucose4()

# Each vertex has exactly one value
for v in range(18):
    solver.add_clause([var_x(v, val) for val in range(34)])
    for val1, val2 in combinations(range(34), 2):
        solver.add_clause([-var_x(v, val1), -var_x(v, val2)])

# Distinct vertex values
for val in range(34):
    for v1, v2 in combinations(range(18), 2):
        solver.add_clause([-var_x(v1, val), -var_x(v2, val)])

# Edge differences
for i, (u, v) in enumerate(edges):
    solver.add_clause([var_e(i, diff) for diff in range(1, 34)])
    for diff in range(1, 34):
        # If e[i][diff] is true, then there must be some val such that x[u][val] and x[v][val+diff] or x[v][val-diff]
        # Actually, it's easier to say: x[u][val] and x[v][val2] => e[i][|val-val2|]
        pass

for i, (u, v) in enumerate(edges):
    for val1 in range(34):
        for val2 in range(34):
            if val1 != val2:
                diff = abs(val1 - val2)
                solver.add_clause([-var_x(u, val1), -var_x(v, val2), var_e(i, diff)])

# Distinct edge differences
for diff in range(1, 34):
    for e1, e2 in combinations(range(33), 2):
        solver.add_clause([-var_e(e1, diff), -var_e(e2, diff)])

# Symmetry breaking
# V[0] < V[1] < V[2]
for val1 in range(34):
    for val2 in range(val1 + 1):
        solver.add_clause([-var_x(0, val1), -var_x(1, val2)])
        solver.add_clause([-var_x(1, val1), -var_x(2, val2)])

# V[0] < V[15]
for val1 in range(34):
    for val2 in range(val1 + 1):
        solver.add_clause([-var_x(0, val1), -var_x(15, val2)])

print("Solving...")
if solver.solve():
    model = solver.get_model()
    res = []
    for v in range(18):
        for val in range(34):
            if model[var_x(v, val) - 1] > 0:
                res.append(val)
    print(res)
else:
    print("UNSAT")
